.fb-done { padding: 14px; border-radius: var(--r-field); background: var(--brand-soft); font-weight: 600; animation: pop .4s var(--ease) both; }
.fb-link { background: none; border: 0; padding: 0; color: var(--band-muted); font: inherit; cursor: pointer; text-decoration: underline; text-underline-offset: 4px; }
