@media (max-width: 640px) {
  .fb-tab { display: none; }
  .fb-panel { right: 12px; left: 12px; width: auto; top: auto; bottom: calc(12px + env(safe-area-inset-bottom, 0px)); transform: translateY(16px); }
  .fb-panel.show { transform: none; }
}
@media (prefers-reduced-motion: reduce) { .pickbar, .fb-panel, .qc-result .checks li { transition-duration: .01s; } }

/* Was ich prüfe: mittig, groß */
.checkpoints .cp-head { text-align: center; max-width: 760px; margin: 0 auto; }
.checkpoints .cp-head .h2 { font-size: clamp(44px, 6.4vw, 84px); line-height: .95; letter-spacing: -.045em; }
