.cp { position: relative; display: grid; align-content: start; gap: 10px; padding: 24px 22px 26px; background: var(--raised); border: 1px solid var(--line); border-radius: var(--r-card); transition: transform .35s var(--ease), box-shadow .35s var(--ease), border-color .35s var(--ease); }
.cp:hover { transform: translateY(-4px); border-color: var(--brand); box-shadow: 0 18px 40px -22px rgba(11,110,105,.55); }
.cp-n { font: 500 15px/1 var(--font-mono); color: var(--brand); display: inline-grid; place-items: center; width: 40px; height: 40px; border-radius: 12px; background: var(--brand-soft); }
