}

/* Terminfelder: kein Überlappen (iOS-Datumsfeld hat eine eigene Mindestbreite) */
.row3 .field { min-width: 0; }
.field input[type="date"] { min-width: 0; max-width: 100%; display: block; -webkit-appearance: none; appearance: none; line-height: 46px; text-align: left; }
