/* Pflichtfelder und Zustimmung */
.req { color: var(--danger); font-weight: 700; }
.req-note { font-size: 13px; color: var(--ink-muted); margin-top: -6px; }
.consent { padding: 12px 14px; border: 1px solid var(--line); border-radius: var(--r-field); background: var(--surface); transition: border-color .2s var(--ease), background-color .2s var(--ease); cursor: pointer; }
