  .foot .big { font-size: clamp(42px, 15.5vw, 56px); }
  .checkpoints .cp-head .h2 { font-size: clamp(32px, 11vw, 44px); }
  .teaser { grid-template-columns: minmax(0, 1fr) clamp(52px, 20vw, 96px); gap: 12px; padding: 20px; }
  .teaser img { width: 100%; height: auto; aspect-ratio: 1 / 1; }
