}
@media (max-width: 360px) { .teaser { padding: 18px 16px; } }
/* Kopfzeile passt sich an, wenn der Platz nicht reicht (große Schrift, schmale Handys, Tablets quer).
   Das Skript setzt die Stufen nacheinander, bis alles in eine Zeile passt. */
html.kopf-nav .menu-btn { display: inline-flex; align-items: center; }
html.kopf-nav .nav { display: none; position: absolute; left: 0; right: 0; top: 100%; flex-direction: column; gap: 0; justify-self: stretch; background: var(--surface); border-bottom: 1px solid var(--line); padding: 8px max(16px, env(safe-area-inset-right, 0px)) 16px max(16px, env(safe-area-inset-left, 0px)); }
html.kopf-nav .nav.open { display: flex; }
