      var per = (17 + (i * 5 + s * 3) % 13) * 1000, ph = i * 1.7 + s * 2.9, A = 0.22, k = Math.max(1, Math.round(d / per));
      var n = Math.min(240, 24 * k), w = 2 * Math.PI * k, teile = ['0'];
