      knopf.innerHTML = '<svg viewBox="0 0 12 12" aria-hidden="true"><path class="ico-halt" d="M2 1h3v10H2zM7 1h3v10H7z"/><path class="ico-weiter" d="M3 1l8 5-8 5z"/></svg>';
      knopf.addEventListener('click', function () {
        ruhe = !ruhe;
